    "authorBio": "李白（701—762），字太白，号青莲居士，唐代最伟大的浪漫主义诗人，被后人尊称为「诗仙」。他出生于西域碎叶城，幼年随家人迁居四川。李白的诗想象奇特、气势磅礴、语言豪放，善于运用夸张和比喻。他一生酷爱饮酒、游历，诗中出现最多的意象是月亮、酒和剑。代表作有《静夜思》《望庐山瀑布》《将进酒》《蜀道难》等。",
    "appreciation": "这首诗描写了天门山的壮丽景色和长江的磅礴气势。前两句「天门中断楚江开，碧水东流至此回」——天门山被长江从中间劈开，碧绿的水流到这里打着回旋。后两句「两岸青山相对出，孤帆一片日边来」——两岸的青山相对而立，一叶小船从太阳那边驶来。全诗气势恢弘，画面开阔。",
    "background": "天门山位于今安徽省，长江流经此处时山势陡峭，形成壮丽的峡谷。李白乘船经过这里，被眼前的景象所震撼，挥笔写下了这首诗。"
