    "authorBio": "王安石（1021—1086），字介甫，号半山，北宋著名政治家、文学家，唐宋八大家之一。他的诗精炼深刻，富有哲理。代表作有《元日》《泊船瓜洲》《梅花》等。",
    "appreciation": "这首诗描写了春节的喜庆气氛。「爆竹声中一岁除」——在爆竹声中送走了旧的一年；「春风送暖入屠苏」——和暖的春风吹来，人们喝着屠苏酒迎接新年。后两句「千门万户曈曈日，总把新桃换旧符」——千家万户都沐浴在初升的阳光中，人们都把旧桃符换成新的。全诗洋溢着辞旧迎新的欢快气氛。",
    "background": "这首诗写于王安石推行变法初期。新年新气象，诗人借春节的喜庆场景，表达了对革新事业的信心和期待。"
