    "sentences": [
      {
        "text": "京口瓜洲一水间，",
        "py": "jīng kǒu guā zhōu yī shuǐ jiān",
        "trans": "京口和瓜洲只隔了一条江水，",
        "words": [
          {
            "word": "京口",
            "note": "今江苏镇江"
          },
          {
            "word": "瓜洲",
            "note": "今江苏扬州南"
          }
        ]
      },
      {
        "text": "钟山只隔数重山。",
        "py": "zhōng shān qí gé shù zhòng shān",
        "trans": "钟山也只隔着几座山。",
        "words": [
          {
            "word": "钟山",
            "note": "今南京紫金山"
          }
        ]
      },
      {
        "text": "春风自绿江南岸，",
        "py": "chūn fēng zì lǜ jiāng nán àn",
        "trans": "",
        "words": []
      },
      {
        "text": "明月何时照我还。",
        "py": "míng yuè hé shí zhào wǒ hái",
        "trans": "明月什么时候才能照着我回家呢？",
        "words": []
      }
    ],
