    "appreciation": "这首诗写牧童捕蝉的生动画面。前两句「牧童骑黄牛，歌声振林樾」——牧童骑着黄牛，歌声在树林中回荡。后两句「意欲捕鸣蝉，忽然闭口立」——他想捉住正在叫的蝉，忽然闭上嘴站住了。从放声高歌到突然闭嘴，一个动作的转变就把牧童的天真机灵写活了。",
    "background": "袁枚是清代诗人。这首诗用白描手法记录了夏日乡村牧童的一个小场景，画面感极强，充满了田园生活的情趣。"
