    "appreciation": "这首诗写风雪夜投宿山中的情景。前两句「日暮苍山远，天寒白屋贫」——太阳落山了，苍茫的山显得更加遥远；天气寒冷，山中那间破旧的小屋更显贫寒。后两句「柴门闻犬吠，风雪夜归人」——柴门外传来狗叫声，在这风雪之夜，是有人回来了。简单的四句话，写出了一幅寒冷冬夜山居的生动画面。",
    "background": "刘长卿是中唐诗人，以写山水隐逸诗见长。这首诗写他在风雪之夜投宿山中的经历，语言简洁却画面感极强。"
