    "authorBio": "孟浩然（689—740），唐代著名山水田园诗人，一生大部分时间隐居在襄阳鹿门山。他的诗清新自然，意境悠远，与王维并称「王孟」。代表作有《春晓》《宿建德江》《过故人庄》等。"
