    "authorBio": "杨万里（1127—1206），字廷秀，号诚斋，南宋著名诗人。他的诗清新活泼，善于捕捉自然中细微的美，形成了独特的「诚斋体」。代表作有《小池》《宿新市徐公店》《晓出净慈寺送林子方》等。"
