    "authorBio": "王维（701—761），字摩诘，号摩诘居士，唐代著名山水田园诗人，被后人称为「诗佛」。他的诗以「诗中有画，画中有诗」著称，用简洁的语言描绘出幽静深远的自然意境。王维多才多艺，同时精通音乐和绘画。代表作有《鹿柴》《山居秋暝》《九月九日忆山东兄弟》《送元二使安西》等。"
